import {lessons,lessonById,chapters} from './catalog.js';
import {sourceIndex} from './coverage.js';
import {exercise,check,answerText} from './models.js';
import {ensureRecord,submit,complete,canComplete,retry,dueLessons,startReview,answerReview,normalize} from './state.js';
import {native,invoke,load,persist,exportData} from './storage.js';
import {guideFor,nativeGuides} from './windows.js';
import {journey,unitProgress,readiness,readinessGates,glossary} from './journey.js';
import {day,pauseOnLoad} from '../engine.js';
import {studyPath,units,unitFor,recommended,nextLesson,phaseFor,phaseNames,phaseAllowed,phasesToSteps,displayTitle,goalFor,progress} from './study.js';

const $=s=>document.querySelector(s);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
const paths={home:'m3 10 9-7 9 7v10H3z M9 20v-7h6v7',book:'M4 4h6l2 2 2-2h6v15h-6l-2 2-2-2H4z M12 6v15',review:'M4 10a8 8 0 1 1 1 8 M4 4v6h6 M12 8v4l3 2',note:'M5 3h14v18H5z M8 7h8 M8 11h8 M8 15h5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l1 1 M18 18l1 1 M5 19l1-1 M18 6l1-1',moon:'M20 15A8 8 0 0 1 9 4 8 8 0 1 0 20 15z',arrow:'M5 12h14 M14 7l5 5-5 5',back:'M19 12H5 M10 7l-5 5 5 5',check:'m5 12 4 4L19 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M9 9a3 3 0 1 1 4 3v2 M12 17h.01',monitor:'M3 4h18v13H3z M8 21h8 M12 17v4',chevron:'m9 5 7 7-7 7',close:'m6 6 12 12 M18 6 6 18',copy:'M8 8h12v13H8z M16 8V3H3v13h5'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[k]?`<path d="${paths[k]}"/>`:''}</svg>`;
const btn=(action,label,cls='secondary',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const linkLesson=(l,label,cls='text-button')=>`<button type="button" class="${cls}" data-lesson="${esc(l.id)}">${label}</button>`;
const badge=(label,cls='')=>`<span class="badge ${cls}">${esc(label)}</span>`;
const reading=text=>String(text).split(/(?<=[.!?])\s+(?=[A-Z])/).reduce((p,s,i)=>{if(i%2===0)p.push(s);else p[p.length-1]+=' '+s;return p;},[]).map(p=>`<p>${esc(p)}</p>`).join('');
let S,view='home',filter='',openUnit='memory',courseTab='lessons',sourceFilter=2,info={},busy=false,toastTimer,saveTimer,searchTimer,vmStep=0,saveFailed=false;
const lesson=()=>lessonById(S.teaching.selected)||studyPath[0];
const record=()=>ensureRecord(S,lesson().id,uid());
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function error(err){console.error(err);toast(err?.message||String(err));refreshSaved();}
function refreshSaved(){document.querySelectorAll('[data-saved]').forEach(n=>{n.textContent=saveFailed?'Save needs attention':'Saved on this device';n.classList.toggle('save-error',saveFailed);});}
async function save(){clearTimeout(saveTimer);try{await persist(S);saveFailed=false;refreshSaved();}catch(err){saveFailed=true;refreshSaved();throw err;}}
function scheduleSave(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>save().catch(error),450);}
function table(t){return `<div class="table-wrap" tabindex="0" role="region" aria-label="Example data"><table><thead><tr>${t.headers.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${t.rows.map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function pageTitle(kicker,title,sub=''){return `<header class="page-heading"><p class="eyebrow">${esc(kicker)}</p><h1 tabindex="-1">${esc(title)}</h1>${sub?`<p class="lede">${esc(sub)}</p>`:''}</header>`;}
function appearanceButtons(){return `<div class="appearance-actions">${btn('theme','', 'icon-text theme-toggle','data-theme-toggle')}${btn('help',icon('help'),'icon-button','aria-label="Help with studying" title="Help with studying"')}</div>`;}
function syncAppearance(){const a=window.ForgeAppearance.get(),dark=a.resolved==='dark';document.querySelectorAll('[data-theme-toggle]').forEach(b=>{b.innerHTML=icon(dark?'sun':'moon')+`<span>${dark?'Light mode':'Dark mode'}</span>`;b.setAttribute('aria-label',`Switch to ${dark?'light':'dark'} mode`);});document.querySelectorAll('[data-theme]').forEach(b=>{if(b.tagName==='BUTTON')b.setAttribute('aria-pressed',String(b.dataset.theme===a.preference));});document.querySelectorAll('[data-size]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.size===a.size)));}
function shell(content){const j=journey(S),active=view==='coverage'?'course':view;return `<div class="app-shell"><a class="skip-link" href="#main">Skip to study</a><aside class="sidebar"><button class="brand" data-view="home" aria-label="OSED Forge study home"><span class="brand-symbol">${icon('book')}</span><span>OSED<span class="brand-forge">FORGE</span><small>Learn. Practise. Build.</small></span></button><p class="nav-caption">YOUR WORKSPACE</p><nav aria-label="Main navigation">${[['home','home','Today'],['course','book','Learning path'],['review','review','Review'],['notebook','note','Notebook'],['exam','monitor','Exam prep']].map(([id,im,label])=>`<button class="nav-item ${active===id?'active':''}" data-view="${id}" ${active===id?'aria-current="page"':''}>${icon(im)}<span>${label}</span>${id==='review'&&dueLessons(S).length?`<span class="nav-count">${dueLessons(S).length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="path-progress"><span>CONCEPTS COMPLETED</span><strong>${j.done}<small> / ${j.total}</small></strong><progress max="${j.total}" value="${j.done}" aria-label="Completed concept lessons"></progress><small>One clear idea at a time.</small></div><button class="nav-item" data-action="glossary">${icon('help')}<span>Word guide</span></button><button class="nav-item ${active==='settings'?'active':''}" data-view="settings">${icon('settings')}<span>Settings</span></button><div class="profile"><span class="avatar">${esc(S.settings.name.slice(0,2).toUpperCase())}</span><span>${esc(S.settings.name)}<small>Personal study space</small></span></div></div></aside><div class="app-body"><header class="workspace-bar"><span class="workspace-label">EXP-301 <span>/</span> Your study journey</span><div class="top-tools"><span class="level-pill">${icon('check')} Level ${j.level}<span>· ${j.xp} XP</span></span>${appearanceButtons()}</div></header><main id="main" tabindex="-1" class="page">${content}</main><footer class="app-footer"><span data-saved>Saved on this device</span><span>OSED Forge · Mission desk 0.4</span></footer></div></div>`;}
function missionPreview(l){if(['bytes','pointers'].includes(l.id))return `<div class="mission-visual"><div class="visual-top"><span>MEMORY LAB</span><span>32-BIT</span></div><div class="byte-diagram"><div class="diagram-label">ADDRESS <small>where it lives</small></div><div class="address-value">0x2000</div><div class="memory-connector">↓</div><div class="value-block"><span>07</span><small>VALUE · WHAT IS STORED</small></div><div class="binary-row">0 0 0 0 <b>0 1 1 1</b></div></div><p>An address is a place.<br>A value is what’s there.</p></div>`;const x=exercise(l.kind,l.id+':worked');return `<div class="mission-visual model-preview"><div class="visual-top"><span>INSIDE THIS LESSON</span><span>32-BIT</span></div><div><h3>${esc(displayTitle(l))}</h3>${table({...x.display,rows:x.display.rows.slice(0,4)})}</div><p>We’ll explain each step<br>before you try it.</p></div>`;}
function home(){const l=recommended(S),r=l?S.teaching.records[l.id]:null,u=l?unitFor(l.id):units.at(-1),j=journey(S),up=unitProgress(S).find(x=>x.id===u?.id),dues=dueLessons(S);return `<div class="home-heading">${pageTitle('LET’S BUILD YOUR SKILLS',`Your next small win, ${S.settings.name}.`,'Learn one idea. Try it. Make it yours.')}<span class="course-label">WINDOWS EXPLOIT DEVELOPMENT</span></div>`+(l?`<section class="mission-card" aria-labelledby="next-title"><div class="mission-copy"><div class="next-meta">${badge(r?'CONTINUE YOUR MISSION':j.done?'YOUR NEXT MISSION':'YOUR FIRST MISSION','accent')}<span>${icon('clock')} ${esc(l.minutes)} min</span><span class="reward-text">+40 XP</span></div><p class="mission-unit">UNIT ${String(units.indexOf(u)+1).padStart(2,'0')} · ${esc(u?.title||'Concept practice')}</p><h2 id="next-title">${esc(displayTitle(l))}</h2><p class="mission-goal">${esc(goalFor(l))}</p><div class="mission-flow"><span>Learn</span><i>›</i><span>See</span><i>›</i><span>Try</span><i>›</i><span>Remember</span></div>${linkLesson(l,`${icon('book')} ${r?'Continue lesson':'Start lesson'}`,'primary start-lesson')}<span class="start-note">${r?`Your place is saved: ${phaseNames[phaseFor(r.step)]}`:'Start here. You only need your curiosity.'}</span></div>${missionPreview(l)}</section>`:`<section class="panel finished"><span class="completion-symbol">${icon('check')}</span><h2>All current concept lessons completed.</h2><p>Keep the ideas fresh, then test them in your Windows lab.</p><button class="primary" data-view="review">Open review</button></section>`)+`<div class="mission-bottom"><section class="path-panel"><div class="section-heading"><div><p class="eyebrow">YOUR CURRENT UNIT</p><h2>${esc(u?.title||'Learning path')}</h2></div><span class="small">${up?.done||0} / ${up?.total||0} complete</span></div><div class="mission-track">${(u?.ids||[]).map((id,i)=>{const item=lessonById(id),done=S.teaching.records[id]?.completed,current=l?.id===id;return `<button class="mission-node ${done?'done':current?'current':''}" data-lesson="${id}" aria-label="${esc(displayTitle(item))}${done?', completed':current?', next lesson':''}"><span class="node-shape">${done?icon('check'):String(i+1).padStart(2,'0')}</span><span class="node-title">${esc(displayTitle(item).replace('Meet the CPU ','').replace('Find your way around a ','').replace('Little-endian storage','Byte order').replace('Where functions return','Returns').replace('PUSH, POP & the stack','The stack').replace('Follow a pointer','Pointers'))}</span>${current?'<small>YOU ARE HERE</small>':''}</button>`;}).join('')}</div><button class="text-button" data-view="course">Explore all ${units.length} units</button></section><section class="reward-panel"><div class="section-heading"><span class="eyebrow">SMALL STEPS ADD UP</span><span class="reward-mark">✦</span></div><h2>Level ${j.level} <span>· ${j.xp} XP</span></h2><progress max="${j.levelSize}" value="${j.levelXP}" aria-label="Experience toward next level"></progress><p>${j.atMaxLevel?'All current study rewards earned.':`${j.xpToNextLevel} XP to your next level.`}</p><div class="reward-rule">${icon('check')} 40 XP for a completed lesson</div><div class="reward-rule">${icon('review')} 10 XP for its first review</div><small>Rewards show practice. Exam skills need lab evidence.</small></section></div><section class="daily-strip"><span class="daily-icon">${icon('review')}</span><div><h2>${dues.length?`${dues.length} short ${dues.length===1?'review is':'reviews are'} ready`:'A little review goes a long way'}</h2><p>${dues.length?'Bring an idea back from memory before your next lesson.':'Finish a lesson today. We’ll bring it back tomorrow.'}</p></div><button class="secondary" data-view="review">${dues.length?'Start review':'View reviews'}</button></section>`;}
function source(l){return `<details class="source-reference"><summary>Related pages in your PDF <span>§${esc(l.sections[0])} · p. ${l.pages[0]}</span></summary><div><p>${esc(l.scope)}</p><p class="small">${esc(l.sections.map(s=>'§'+s).join(', '))} · ${l.pages[0]===l.pages[1]?'Page '+l.pages[0]:'Pages '+l.pages.join('–')}. These are topic references in your EXP-301 v1.0 edition, not a whole-chapter reading assignment. The lesson above uses original explanations and examples.</p>${native?btn('pdf',`Open my PDF · navigate to page ${l.pages[0]}`,'secondary'):'<p class="small">Keep your own PDF open only when you need the original context.</p>'}</div></details>`;}
function phaseNav(r){const phase=phaseFor(r.step);return `<nav class="lesson-steps" aria-label="Lesson progress">${phaseNames.map((name,i)=>{const allowed=phaseAllowed(r,i)&&i<=phase;return `<button type="button" data-phase="${i}" class="${i===phase?'current':i<phase?'past':''}" ${allowed?'':'disabled'} ${i===phase?'aria-current="step"':''}><span>${i<phase?icon('check'):i+1}</span><b>${name}</b></button>`;}).join('')}</nav>`;}
function focusScreen(){const l=lesson(),r=record(),u=unitFor(l.id);return `<div class="focus-shell"><header class="focus-header"><button class="back-link" data-view="home">${icon('back')}<span>Back to study</span></button><div class="focus-unit">${esc(u?.title||'Getting started')}</div><div class="focus-tools">${btn('glossary','Words','icon-text','aria-label="Open technical word guide"')}${btn('type','Aa','icon-button type-button','aria-label="Change reading size" title="Reading size"')}${appearanceButtons()}</div></header><main id="main" tabindex="-1" class="reader">${r.step===5?'':phaseNav(r)}<header class="reader-heading"><div class="eyebrow">${r.step===5?'WINDOWS PRACTICE':`LESSON ${Math.max(1,studyPath.indexOf(l)+1)} · ${l.minutes} MIN`}</div><h1 tabindex="-1">${esc(displayTitle(l))}</h1></header>${stage(l,r)}${source(l)}<div class="reader-saved" data-saved>Saved on this device</div></main></div>`;}
function memoryIllustration(l){if(!['bytes','pointers'].includes(l.id))return '';return `<figure class="memory-illustration"><figcaption>A tiny memory example</figcaption><div class="memory-layout"><div class="memory-address"><span>ADDRESS · WHERE</span><code>0x2000</code><small>The location label</small></div><span class="memory-arrow" aria-hidden="true">${icon('arrow')}</span><div class="memory-cell"><span>VALUE · WHAT</span><code>7</code><small>The ${l.id==='bytes'?'byte':'DWORD'} stored here</small></div></div><p>The address tells you where to look. The value tells you what is there.</p></figure>`;}
function modelState(x,i){const s=x.states?.[i];return s?`<details class="state-detail"><summary>See registers and memory at this step</summary><div class="register-row">${Object.entries(s.registers).map(([k,v])=>`<div><span>${esc(k)}</span><code>${esc(v)}</code></div>`).join('')}</div>${table({headers:['Address','Stored value','Meaning'],rows:s.memory})}<p class="small">Illustrative state, not a live debugger.</p></details>`:'';}
function stage(l,r){
 if(r.step===0)return `<article class="lesson-sheet"><p class="sheet-label">The idea</p><div class="reading-copy">${reading(l.explain)}</div>${memoryIllustration(l)}<details class="analogy"><summary>${icon('help')} Explain it more simply</summary><p>${esc(l.simple)}</p></details><details class="practice-tip"><summary>What should I focus on?</summary><p>${esc(l.practice)}</p></details><div class="lesson-footer"><span>Next: see this idea in action</span>${btn('watch',`Show me an example ${icon('arrow')}`,'primary')}</div></article>`;
 if(r.step===1){const x=exercise(l.kind,l.id+':worked'),i=Math.min(r.watch,x.steps.length-1);return `<article class="lesson-sheet"><div class="sheet-top"><p class="sheet-label">Watch it happen</p><span class="small">Example · no answer needed</span></div><h2>${esc(x.prompt)}</h2>${table(x.display)}<div class="worked-step" aria-live="polite"><span class="work-number">${i+1}</span><div><span class="eyebrow">STEP ${i+1} OF ${x.steps.length}</span><p>${esc(x.steps[i])}</p></div></div>${modelState(x,i)}<div class="lesson-footer">${btn(i?'watch-back':'understand',`${icon('back')} ${i?'Previous step':'Back'}`,'text-button')}${i<x.steps.length-1?btn('watch-next',`Next step ${icon('arrow')}`,'primary'):btn('guided',`Try with guidance ${icon('arrow')}`,'primary')}</div><p class="model-note">Original teaching example · simplified model</p></article>`;}
 if(r.step===2||r.step===3)return `<article class="lesson-sheet">${practice(l,r[r.step===2?'guided':'solo'],r.step===2?'guided':'solo',r.completed)}</article>`;
 if(r.step===4)return recap(l,r);
 return windows(l,r);
}
function practice(l,t,part,completed=false,reviewMode=false){const x=exercise(l.kind,t.seed),done=reviewMode?S.teaching.review.recorded:t.correct||t.revealed,clean=t.correct&&!t.revealed&&!t.hints&&t.tries===1;return `<div class="sheet-top"><p class="sheet-label">${reviewMode?'A quick review':part==='guided'?'Try with guidance':'Now try it yourself'}</p><span class="small">${reviewMode?'Already learned':part==='guided'?'Practice 1 of 2':'Practice 2 of 2'}</span></div><p class="practice-intro">${reviewMode?'Recall the idea, then check your answer.':part==='guided'?'Use a hint whenever you need one. This question is for learning.':'Same idea, different values. Try this one without a hint.'}</p><h2>${esc(x.prompt)}</h2>${table(x.display)}<form novalidate id="answer-form" data-part="${part}" data-review="${reviewMode}">${x.answerType==='choice'?`<fieldset class="answer-choices"><legend>Your answer</legend>${x.options.map((o,i)=>`<label class="answer-option ${t.answer===String(i)?'chosen':''}"><input type="radio" name="answer" value="${i}" ${t.answer===String(i)?'checked':''} ${done?'disabled':''} required><span>${esc(o)}</span></label>`).join('')}</fieldset>`:`<label class="answer-label" for="answer">${x.answerType==='bytes'?'Write four byte pairs':'Your answer'}</label><input class="answer-input" id="answer" name="answer" autocomplete="off" spellcheck="false" maxlength="160" value="${esc(t.answer)}" ${done?'disabled':''} required aria-describedby="answer-help"><small id="answer-help">${x.answerType==='bytes'?'For example: 12 34 56 78':'Use decimal, or hexadecimal with 0x at the start.'}</small>`}${!done?`<div class="answer-actions"><button type="submit" class="primary">Check answer ${icon('check')}</button>${!reviewMode?btn('hint','I need a hint','text-button'):''}</div>`:''}</form>${t.hints?`<aside class="hint" aria-live="polite"><strong>A hint for you</strong>${x.hints.slice(0,t.hints).map(h=>`<p>${esc(h)}</p>`).join('')}</aside>`:''}${t.tries||t.revealed?`<section class="feedback ${t.correct?'good':'try-again'}" role="status"><h3>${icon(t.correct?'check':'help')} ${t.correct?'That’s right.':t.revealed?'Let’s walk through it.':'Let’s look at why.'}</h3><p>${esc(x.explanation)}</p>${t.correct||t.revealed||reviewMode?`<p class="answer-result">Answer: <strong>${esc(answerText(x))}</strong></p><details><summary>Show every step</summary>${x.steps.map(s=>`<p>${esc(s)}</p>`).join('')}</details>`:`<p>${esc(x.hints[0])}</p>${!reviewMode?btn('reveal','Show the worked solution','text-button'):''}`}</section>`:''}${reviewMode?(done?`<div class="lesson-footer"><span>${t.correct?'You remembered it.':'We’ll revisit this tomorrow.'}</span>${btn('end-review',`Continue ${icon('arrow')}`,'primary')}</div>`:''):`<div class="lesson-footer"><span class="small">${part==='guided'?'A simplified exercise—not a live Windows lab.':clean?'Independent question passed.':t.tries||t.hints||t.revealed?'You can always try a fresh question.':''}</span>${part==='guided'&&t.correct?btn('solo',`Try on my own ${icon('arrow')}`,'primary'):part==='solo'&&clean?btn('remember',`Finish with a recap ${icon('arrow')}`,'primary'):!completed&&(done||(part==='solo'&&t.tries>0))?btn('fresh-'+part,`Try a fresh question ${icon('arrow')}`,'primary'):''}</div>`}`;}
function recap(l,r){const g=guideFor(l),next=nextLesson(l.id),ready=canComplete(r);return `<article class="lesson-sheet">${r.completed?`<div class="lesson-complete"><span class="completion-symbol">${icon('check')}</span><p class="sheet-label">Lesson complete</p><h2>Mission complete.</h2><div class="earned-reward">✦ 40 XP earned for this lesson</div><p>We’ll bring this back for a short review on ${esc(r.due)}.</p></div>`:`<p class="sheet-label">Make it stick</p><h2>What clicked for you?</h2><p class="reading-copy">Explain the idea in your own words, or name one mistake you’ll avoid next time.</p>`}<label class="answer-label" for="reflection">Your recap</label><textarea id="reflection" maxlength="5000" rows="4" placeholder="The key difference is…">${esc(r.reflection)}</textarea><small>${r.completed?'Your own notes; not an automatically graded essay.':'Write a short sentence (at least 12 characters). Your notes stay on this device.'}</small>${!r.completed?`<div class="lesson-footer"><span id="recap-help" class="small">${r.reflection.trim().length<12?'Add a sentence to finish.':ready?'Ready to save your lesson.':'Finish the two practice questions first.'}</span>${btn('complete',`Complete lesson ${icon('check')}`,'primary',ready?'':'disabled')}</div>`:`<div class="lesson-footer"><button class="text-button" data-view="home">Back to study</button>${next?linkLesson(next,`Next: ${esc(displayTitle(next))} ${icon('arrow')}`,'primary'):'<button class="primary" data-view="review">Go to review</button>'}</div>`}${r.completed&&g?`<section class="optional-lab"><span>${icon('monitor')}</span><div><h3>Take it into WinDbg</h3><p>Optional next step · a real observation lab in your Windows VM.</p>${btn('windows','Open Windows walkthrough','text-button')}</div></section>`:''}</article>`;}
function windows(l,r){const g=guideFor(l);if(!g)return `<article class="lesson-sheet"><h2>Windows practice for this topic</h2><p>This lesson includes concept practice. A native target for this topic is not included in this release.</p><p>Your course references are below; use your licensed environment for the original exercise.</p>${btn('remember','Back to recap','primary')}</article>`;const i=Math.min(vmStep,g.steps.length-1),s=g.steps[i];return `<article class="lesson-sheet"><p class="sheet-label">Original Windows observation lab</p><h2>${esc(g.title)}</h2><p>${esc(g.goal)}</p><details class="lab-setup"><summary>Before you start · lab pack & Windows VM</summary><p>Use lesson_lab.exe and its matching PDB from the separate foundation lab pack, inside a disposable Windows VM. This is observation practice, not an exploitation challenge.</p><p>The existing v0.2 lab pack is compatible. No targets or debuggers are automatically installed.</p></details><div class="worked-step"><span class="work-number">${i+1}</span><div><span class="eyebrow">STEP ${i+1} OF ${g.steps.length}</span><h3>${esc(s[0])}</h3><pre><code>${esc(s[1])}</code></pre>${btn('copy-command',`${icon('copy')} Copy command / instructions`,'text-button')}<p><strong>What to expect</strong><br>${esc(s[2])}</p></div></div><div class="lesson-footer">${btn(i?'vm-back':'leave-lab',`${icon('back')} ${i?'Previous step':'Back to labs'}`,'text-button')}${i<g.steps.length-1?btn('vm-next',`Next step ${icon('arrow')}`,'primary'):btn('leave-lab','Finish walkthrough','primary')}</div><details class="observation-notes"><summary>Record what you observed</summary><p>${esc(g.question)}</p><label for="native-note">Your debugger observations</label><textarea id="native-note" rows="4" maxlength="10000">${esc(r.nativeNote)}</textarea><small>These notes are self-reported, not an automated lab grade.</small></details></article>`;}
function course(){return pageTitle('YOUR LEARNING PATH','Find your place.','Follow the suggested order, or revisit a concept you need.')+`<div class="course-toolbar"><div class="segmented" role="group" aria-label="Course view"><button data-course-tab="lessons" aria-pressed="${courseTab==='lessons'}">Lessons</button><button data-course-tab="labs" aria-pressed="${courseTab==='labs'}">Windows labs</button></div><button class="text-button" data-view="coverage">Source map ${icon('arrow')}</button></div>`+(courseTab==='labs'?labLibrary():`<div class="search-field"><label for="lesson-search" class="sr-only">Search lessons</label><input id="lesson-search" type="search" placeholder="Find a lesson…" value="${esc(filter)}">${filter?btn('clear-search','Clear search','text-button'):''}</div><div class="unit-list">${units.map((u,idx)=>{const ls=u.ids.map(lessonById).filter(l=>`${l.title} ${l.sections.join(' ')} ${displayTitle(l)}`.toLowerCase().includes(filter.toLowerCase()));if(!ls.length)return '';const done=u.ids.filter(id=>S.teaching.records[id]?.completed).length;return `<details class="unit" data-unit="${u.id}" ${filter||u.id===openUnit?'open':''}><summary><span class="unit-number">${String(idx+1).padStart(2,'0')}</span><span><strong>${esc(u.title)}</strong><small>${done} / ${u.ids.length} lessons complete</small></span><span class="unit-chevron">${icon('chevron')}</span></summary><p class="unit-description">${esc(u.description)}</p>${ls.map(l=>{const r=S.teaching.records[l.id],isNext=recommended(S)?.id===l.id;return `<button class="lesson-row" data-lesson="${l.id}"><span class="lesson-status ${r?.completed?'done':isNext?'next':''}">${r?.completed?icon('check'):isNext?icon('arrow'):''}</span><span class="lesson-name">${esc(displayTitle(l))}<small>${esc(l.minutes)} min${r&&!r.completed?' · In progress':''}</small></span>${isNext?badge('Your next lesson','accent'):r?.completed?'<span class="small">Revisit</span>':''}${icon('chevron')}</button>`;}).join('')}</details>`;}).join('')||'<section class="panel"><h2>No matching lessons.</h2><p>Try “pointer”, “stack” or “WinDbg”.</p></section>'}</div>`);}
function labLibrary(){return `<p class="muted">Five guided observation labs. You’ll need the lab pack and a Windows VM.</p><div class="lab-library">${Object.values(nativeGuides).map(g=>{const l=studyPath.find(l=>guideFor(l)===g);return l?`<article class="panel"><span class="lab-icon">${icon('monitor')}</span><h2>${esc(g.title)}</h2><p>${esc(g.goal)}</p><button class="secondary" data-native="${l.id}">Open walkthrough ${icon('arrow')}</button></article>`:'';}).join('')}</div><details class="source-reference"><summary>What about advanced exploit labs?</summary><p>The advanced lessons currently contain simplified model practice. Full native integration challenges are not included; the source map keeps those gaps visible.</p></details>`;}
function review(){const q=S.teaching.review,dues=dueLessons(S);return pageTitle('A LITTLE REPETITION','Keep the ideas fresh.','Only concepts you’ve already completed appear here.')+(q?`<section class="panel review-practice"><h2 class="review-title">${esc(displayTitle(lessonById(q.id)))}</h2>${practice(lessonById(q.id),q.trial,'review',false,true)}${!q.recorded?btn('end-review','Save this for later','text-button'):''}</section>`:dues.length?`<section class="panel"><h2>${dues.length} ${dues.length===1?'lesson is':'lessons are'} ready to review.</h2><p>Each check uses a fresh example of an idea you’ve learned.</p>${dues.slice(0,5).map(l=>`<button class="review-row" data-review-id="${l.id}"><span>${esc(displayTitle(l))}</span>${icon('arrow')}</button>`).join('')}</section>`:`<section class="panel empty-state"><span class="empty-icon">${icon('review')}</span><h2>You’re all caught up.</h2><p>${progress(S).done?'Your next reviews appear when they’re due.':'Finish your first lesson. A short review will be ready the next day.'}</p><button class="primary" data-view="home">Back to today ${icon('arrow')}</button></section>`);}
function notebook(){const notes=Object.entries(S.teaching.records).filter(([,r])=>r.reflection||r.nativeNote);return pageTitle('YOUR NOTEBOOK','The things that clicked.','Your recaps and Windows observations, kept together.')+`<div class="section-heading"><span class="muted">${notes.length} lesson ${notes.length===1?'note':'notes'}</span>${btn('export','Export backup','secondary')}</div>${notes.length?notes.map(([id,r])=>`<article class="panel note-entry"><div class="section-heading"><h2>${esc(displayTitle(lessonById(id)))}</h2>${r.completed?badge('Completed','success'):badge('In progress')}</div><p class="pre reading-copy">${esc(r.reflection||'No recap yet.')}</p>${r.nativeNote?`<details><summary>Windows observations</summary><p class="pre">${esc(r.nativeNote)}</p></details>`:''}${linkLesson(lessonById(id),`Revisit lesson ${icon('arrow')}`)}</article>`).join(''):`<section class="panel empty-state"><span class="empty-icon">${icon('note')}</span><h2>Your first note starts with a lesson.</h2><p>Write a short recap when you finish. It will be waiting here.</p><button class="primary" data-view="home">Go to today ${icon('arrow')}</button></section>`}<details class="panel"><summary>Study sessions & earlier notes</summary><form novalidate id="session-form" class="session-form"><label>Topic<input name="topic" maxlength="180" required placeholder="What did you study?"></label><label>Minutes<input type="number" name="minutes" min="1" max="720" value="20" required></label><button class="secondary">Save session</button></form>${S.sessions.slice(-20).reverse().map(s=>`<div class="session-row"><span>${esc(s.topic)}</span><small>${esc(s.date)} · ${s.minutes} min</small></div>`).join('')}${Object.entries(S.chapters).filter(([,c])=>c.note).map(([id,c])=>`<h3>Chapter ${id}</h3><p class="pre">${esc(c.note)}</p>`).join('')}<p class="small">Earlier attempts, quiz history and timers are retained in your full backup.</p></details>`;}
function coverage(){return pageTitle('OPTIONAL REFERENCE','The source map.','See which parts of the course have a related lesson, and what remains unfinished.')+`<p class="notice">A related concept lesson is not a completed native exercise. Detailed case studies and advanced lab conversions remain unfinished.</p><label class="source-filter">Show one chapter<select id="source-filter">${chapters.slice(1).map((t,i)=>`<option value="${i+1}" ${sourceFilter===i+1?'selected':''}>${i+1} · ${esc(t)}</option>`).join('')}</select></label><div class="source-list">${sourceIndex.filter(s=>s.chapter===sourceFilter).map(s=>{const ls=lessons.filter(l=>l.sections.includes(s.section));return `<article><div class="small">§${esc(s.section)} · p. ${s.page}</div><h3>${esc(s.title)}</h3><p class="small">${s.type==='exercise'?'Native exercise conversion pending':ls.length?'Related concept lesson available':s.type==='reference'?'Source / dated administration':'Detailed lesson conversion pending'}</p>${s.type!=='exercise'?ls.map(l=>linkLesson(l,`${esc(displayTitle(l))} ${icon('arrow')}`)).join(''):''}</article>`;}).join('')}</div>`;}

function exam(){const e=readiness(S);return pageTitle('PRACTISE FOR THE REAL TASK','Build evidence, then confidence.','Use your own lab results to see what needs more work.')+`<section class="exam-facts"><div><strong>3</strong><span>independent tasks</span></div><div><strong>47h 45m</strong><span>exam time</span></div><div><strong>24h</strong><span>reporting time</span></div><div><strong>60 / 100</strong><span>official pass mark</span></div></section><p class="source-credit">Rules checked 1 October 2026 · <a href="https://help.offsec.com/hc/en-us/articles/360052977212-EXP-301-Windows-User-Mode-Exploit-Development-OSED-Exam-Guide" target="_blank" rel="noreferrer">Read the official exam guide</a></p><section class="panel"><h2>Your preparation checklist</h2><p>These are your own checks, not verified results. XP and concept completion do not predict an exam pass.</p><div class="readiness-list">${e.gates.map((g,i)=>`<details class="readiness-gate"><summary><span class="gate-number ${g.checked?'reported':''}">${g.checked?icon('check'):String(i+1).padStart(2,'0')}</span><span><strong>${esc(g.title)}</strong><small>${g.checked?'Self-reported complete':'Evidence needed'}</small></span>${icon('chevron')}</summary><div class="gate-content"><p>${esc(g.description)}</p><label class="check-label"><input type="checkbox" data-gate="${g.id}" ${g.checked?'checked':''}>I have checked this with my own practical work.</label><small>This marks your checklist only. It does not verify a lab.</small></div></details>`).join('')}</div></section><section class="panel"><h2>Record a lab result</h2><p>Use an authorized course lab or your own test VM. Write what you observed and how you checked it. Your draft stays on this device until you save it.</p><form novalidate id="evidence-form"><div class="two-fields"><label>Skill<select name="gate">${readinessGates.map(g=>`<option value="${g.id}">${esc(g.title)}</option>`).join('')}</select></label><label>How did you work?<select name="status"><option value="assisted">With guidance</option><option value="independent">On my own</option><option value="reproduced">Repeated from a clean reset</option><option value="blocked">Still stuck</option></select></label></div><label class="answer-label" for="evidence-note">Lab name and evidence</label><textarea id="evidence-note" name="note" required minlength="20" maxlength="10000" rows="5" placeholder="Lab name: …&#10;What happened: …&#10;How I checked it: …&#10;What I need to fix: …"></textarea><div class="two-fields"><label>Minutes spent<input type="number" name="minutes" min="0" max="1440" value="30" required></label><label>Hints used<select name="hints"><option value="0">None</option><option value="1">1 hint</option><option value="2">2 hints</option><option value="3">3 or more hints</option></select></label></div><label class="check-label"><input type="checkbox" name="passed">I met the lab’s objective.</label><button class="primary">Save lab evidence</button></form></section>${S.attempts.filter(a=>a.labId.startsWith('gate-')).length?`<section class="panel"><h2>Recent lab notes <span class="small">Self-reported</span></h2>${S.attempts.filter(a=>a.labId.startsWith('gate-')).slice(-8).reverse().map(a=>`<article class="evidence-note"><div class="section-heading"><strong>${esc(readinessGates.find(g=>'gate-'+g.id===a.labId)?.title||'Lab result')}</strong>${badge(a.status==='reproduced'?'Clean reset':a.status==='independent'?'On my own':a.status==='blocked'?'Still stuck':'With guidance')}</div><p class="pre">${esc(a.note)}</p><small>${esc(a.date)} · ${a.minutes} min · ${a.hints} ${a.hints===1?'hint':'hints'} · ${a.passed?'Objective met':'More work needed'}</small></article>`).join('')}</section>`:''}<section class="exam-boundary"><h2>Practise under exam conditions</h2><p>Use Python 3, IDA Freeware and WinDbg. For a solo rehearsal, work without hints or AI help, then write a report that someone else can follow. The real exam prohibits chatbot assistance.</p><p>This app includes concept practice and five observation walkthroughs. Use your purchased course for the advanced exploit labs and Challenge Labs. Those complete targets are not bundled here.</p></section>`;}
function glossaryDialog(){const d=$('#modal');d.className='glossary-dialog';d.innerHTML=`<header class="dialog-heading"><h2>Technical words, simple meanings</h2><button data-close aria-label="Close word guide">${icon('close')}</button></header><p>Keep the technical word. Learn what it means.</p><dl class="glossary-list">${glossary.map(g=>`<div><dt>${esc(g.term)}</dt><dd>${esc(g.definition)}${g.example?`<code>${esc(g.example)}</code>`:''}</dd></div>`).join('')}</dl>`;d.setAttribute('aria-label','Technical word guide');d.showModal();}
const draftIds=['settings-form','session-form','evidence-form'];
let drafts={};try{drafts=JSON.parse(localStorage.getItem('osed-forge-form-drafts')||'{}');if(!drafts||typeof drafts!=='object'||Array.isArray(drafts))drafts={};}catch{}
function writeDrafts(){try{localStorage.setItem('osed-forge-form-drafts',JSON.stringify(drafts));}catch{toast('This browser cannot save form drafts. Keep this page open until you save.');}}
function keepDraft(f){if(!f||!draftIds.includes(f.id))return;drafts[f.id]=Object.fromEntries([...f.elements].filter(x=>x.name).map(x=>[x.name,x.type==='checkbox'?x.checked:x.value]));writeDrafts();}
function clearDraft(id){if(drafts[id]){delete drafts[id];writeDrafts();}}
function restoreDrafts(){for(const id of draftIds){const f=document.getElementById(id),d=drafts[id];if(!f||!d||typeof d!=='object'||Array.isArray(d))continue;for(const el of f.elements){if(!el.name||!(el.name in d))continue;if(el.type==='checkbox')el.checked=!!d[el.name];else el.value=String(d[el.name]);}}}
function validateForm(f){f.querySelector('.form-error')?.remove();for(const input of f.querySelectorAll('input,textarea,select'))input.removeAttribute('aria-invalid');const bad=[...f.querySelectorAll('input,textarea,select')].find(x=>!x.validity.valid||(x.required&&!x.value.trim())||(x.minLength>0&&x.value.length<x.minLength));if(!bad)return true;const error=document.createElement('p');error.className='form-error';error.id='form-error';error.setAttribute('role','alert');error.textContent=bad.name==='note'?'Add the lab name and a short explanation (at least 20 characters).':bad.name==='answer'?'Enter or choose an answer before checking.':`Check ${bad.closest('label')?.childNodes[0]?.textContent?.trim()||bad.name||'this field'} and enter a valid value.`;f.prepend(error);bad.setAttribute('aria-invalid','true');bad.setAttribute('aria-describedby','form-error');bad.focus();return false;}
function confirmImport(){return new Promise(resolve=>{const d=$('#modal');d.className='';d.setAttribute('aria-label','Replace saved progress');d.innerHTML=`<header class="dialog-heading"><h2>Replace saved progress?</h2></header><p>This backup will replace this device’s journal and clear any unsaved study-plan draft. Export your current progress first if you want to keep a copy.</p><div class="dialog-actions"><button class="secondary" data-import-cancel autofocus>Cancel</button><button class="primary" data-import-confirm>Replace with backup</button></div>`;const finish=value=>{d.removeEventListener('close',closed);d.close();resolve(value);};const closed=()=>resolve(false);d.addEventListener('close',closed,{once:true});d.querySelector('[data-import-cancel]').onclick=()=>finish(false);d.querySelector('[data-import-confirm]').onclick=()=>finish(true);d.showModal();d.querySelector('[data-import-cancel]').focus();});}
function appearanceSettings(){return `<section class="panel"><div class="setting-heading">${icon('sun')}<div><h2>Make yourself comfortable.</h2><p>Change the look without changing your progress.</p></div></div><label class="control-label">Appearance</label><div class="segmented theme-options" role="group" aria-label="Appearance">${[['system','monitor','System'],['light','sun','Light'],['dark','moon','Dark']].map(([v,i,label])=>`<button type="button" data-theme="${v}" aria-pressed="false">${icon(i)} ${label}</button>`).join('')}</div><p class="small">System follows your device. Your choice stays saved on this device.</p><label class="control-label">Lesson text size</label><div class="segmented" role="group" aria-label="Lesson text size">${[['small','Standard'],['medium','Comfortable'],['large','Large']].map(([v,t])=>`<button type="button" data-size="${v}" aria-pressed="false">${t}</button>`).join('')}</div><p class="text-preview reading-copy">An address is a place. A value is what’s stored there.</p></section>`;}
function settings(){return pageTitle('SETTINGS','Your space, your pace.','Everything you need to start studying already works offline.')+appearanceSettings()+`<div class="settings-columns"><form novalidate id="settings-form" class="panel settings-form"><h2>Your study plan</h2><label>Name<input name="name" maxlength="60" required value="${esc(S.settings.name)}"></label><div class="two-fields"><label>Start date<input name="startDate" type="date" required value="${esc(S.settings.startDate)}"></label><label>Hours per week<input name="weeklyHours" type="number" min="1" max="60" step="0.5" required value="${S.settings.weeklyHours}"></label></div><details><summary>Course access dates · optional</summary><label>Actual lab start<input name="labStart" type="date" value="${esc(S.settings.labStart)}"></label><label>Actual lab expiry<input name="labEnd" type="date" value="${esc(S.settings.labEnd)}"></label><label>Actual exam expiry<input name="examExpiry" type="date" value="${esc(S.settings.examExpiry)}"></label><p class="small">Enter your real portal dates. A study plan does not extend paid access.</p></details><button class="secondary">Save study plan</button></form><section class="panel"><h2>Backup & reference</h2><p>Save a copy of your complete journal before upgrading or switching devices.</p>${btn('export','Export backup','secondary')}<label class="file-label">Import backup<input id="import" type="file" accept=".json,application/json"></label><p class="small">Import replaces your journal after validation and confirmation. It does not merge. Appearance preferences stay device-local.</p><details><summary>Link your PDF · optional</summary><p>You don’t need the PDF for the in-app lessons. Link it for the exact source references.</p>${native?btn('select-pdf',info.pdf?`Change PDF · ${esc(info.pdf)}`:'Choose my local PDF','secondary'):'<p class="small">Local PDF linking is available in the Windows application.</p>'}</details></section></div><details class="panel"><summary>About this release</summary><p>OSED Forge 0.4 · Mission desk. ${lessons.length} authored lessons, including the orientation guide. ${studyPath.length} lessons on the learning path. Five Windows observation walkthroughs. No live AI service, automatic phone synchronization or background reminders.</p><p>Advanced native exploit labs remain unfinished. Concept checks and your own notes are not an exam-readiness certification.</p><p class="small">Database: ${esc(info.database||'Browser IndexedDB')}. Existing notes and attempts are retained. Avoid opening older app versions against your upgraded journal.</p></details>`;}
function render(focus=false){if(!S)return;document.title=`${view==='lesson'?displayTitle(lesson()):({home:'Today',course:'Learning path',review:'Review',notebook:'Notebook',exam:'Exam prep',settings:'Settings',coverage:'Source map'})[view]} · OSED Forge`;document.body.classList.toggle('in-lesson',view==='lesson');$('#app').innerHTML=view==='lesson'?focusScreen():shell(({home,course,review,notebook,settings,coverage,exam})[view]());syncAppearance();refreshSaved();restoreDrafts();try{sessionStorage.setItem('osed-forge-view',view);}catch{}if(focus){window.scrollTo({top:0,behavior:'instant'});$('#main h1')?.focus({preventScroll:true});}}
function go(v){if(!['home','lesson','course','review','notebook','settings','coverage','exam'].includes(v))return;view=v;render(true);}
function move(n){record().step=n;render(true);save().catch(error);}
function openLesson(id,nativeStep=false){const l=lessonById(id);if(!l)throw new Error('This lesson is not available.');S.teaching.selected=id;const r=ensureRecord(S,id,uid());if(nativeStep)r.step=5;else if(r.step===5)r.step=r.completed?4:0;vmStep=0;openUnit=unitFor(id)?.id||'memory';view='lesson';render(true);return save();}
function helpDialog(type='help'){const d=$('#modal');d.className='';d.innerHTML=type==='type'?`<header class="dialog-heading"><h2>Reading size</h2><button data-close aria-label="Close">${icon('close')}</button></header><p>Choose a comfortable size for the lesson text.</p><div class="segmented" role="group" aria-label="Reading size">${[['small','Standard'],['medium','Comfortable'],['large','Large']].map(([v,t])=>`<button data-size="${v}" aria-pressed="false">${t}</button>`).join('')}</div>`:`<header class="dialog-heading"><h2>Here’s how to study.</h2><button data-close aria-label="Close">${icon('close')}</button></header><ol class="help-steps"><li><b>Start the next lesson.</b><p>Today picks a sensible place to begin or resume.</p></li><li><b>Understand, then practise.</b><p>Read one idea. Follow the example. Try two short questions.</p></li><li><b>Write a recap and move on.</b><p>Your notes save automatically. A short review comes later.</p></li></ol><p class="muted">You do not need a PDF or a VM for the concept lessons. Windows labs are a separate option after learning the idea.</p><button class="primary" data-close>Got it</button>`;d.setAttribute('aria-label',type==='type'?'Reading size':'How to study');d.showModal();syncAppearance();}
async function action(a){if(a==='glossary'){glossaryDialog();return;}if(a==='clear-search'){clearTimeout(searchTimer);filter='';render();$('#lesson-search')?.focus();return;}if(a==='theme'){window.ForgeAppearance.toggle();return;}if(a==='type'||a==='help'){helpDialog(a);return;}if(a==='export'){const out=await exportData(S);toast(out?'Backup exported.':'Export cancelled.');return;}const r=record(),l=lesson();switch(a){
 case 'understand':move(0);return;
 case 'watch':move(1);return;
 case 'watch-next':r.watch=Math.min(r.watch+1,exercise(l.kind,l.id+':worked').steps.length-1);break;
 case 'watch-back':r.watch=Math.max(0,r.watch-1);break;
 case 'guided':move(2);return;
 case 'solo':if(!r.guided.correct)throw new Error('Check the guided question first.');move(3);return;
 case 'remember':move(4);return;
 case 'windows':move(5);return;
 case 'hint':{if(r.completed)return;const t=r[r.step===2?'guided':'solo'];t.hints=Math.min(3,t.hints+1);break;}
 case 'reveal':if(!r.completed)r[r.step===2?'guided':'solo'].revealed=true;break;
 case 'fresh-guided':case 'fresh-solo':retry(r,a.slice(6),uid(),l.kind);break;
 case 'complete':r.reflection=$('#reflection')?.value||r.reflection;complete(r);toast('Mission complete! Your lesson and recap are saved.');break;
 case 'leave-lab':r.step=r.completed?4:0;courseTab='labs';view='course';break;
 case 'vm-back':vmStep=Math.max(0,vmStep-1);break;
 case 'vm-next':vmStep=Math.min(vmStep+1,guideFor(l).steps.length-1);break;
 case 'copy-command':await navigator.clipboard.writeText(guideFor(l).steps[vmStep][1]);toast('Copied.');return;
 case 'end-review':S.teaching.review=null;break;
 case 'select-pdf':info.pdf=await invoke('select_pdf');break;
 case 'pdf':if(!info.pdf){info.pdf=await invoke('select_pdf');if(!info.pdf)return;}await invoke('open_pdf');toast(`In your PDF: page ${l.pages[0]}, §${l.sections[0]}.`);return;
 default:return;
 }await save();render();}

