document.addEventListener('change',async ev=>{if(!S)return;const t=ev.target;keepDraft(t.closest('form'));try{if(t.type==='radio'&&t.name==='answer')document.querySelectorAll('.answer-option').forEach(n=>n.classList.toggle('chosen',n.querySelector('input').checked));if(t.dataset.gate){S.checks=S.checks.filter(id=>id!==t.dataset.gate);if(t.checked)S.checks.push(t.dataset.gate);await save();toast('Your self-check is saved.');const gate=t.closest('details');gate.querySelector('summary small').textContent=t.checked?'Self-reported complete':'Evidence needed';const n=gate.querySelector('.gate-number');n.classList.toggle('reported',t.checked);n.innerHTML=t.checked?icon('check'):String(readinessGates.findIndex(g=>g.id===t.dataset.gate)+1).padStart(2,'0');}if(t.id==='source-filter'){sourceFilter=Number(t.value);render();}if(t.id==='import'&&t.files[0]){if(t.files[0].size>4*1024*1024)throw new Error('Backup exceeds the 4 MiB limit.');const candidate=normalize(JSON.parse(await t.files[0].text()));if(!await confirmImport())return;clearTimeout(saveTimer);await persist(candidate);S=candidate;clearDraft('settings-form');pauseOnLoad(S.timer);go('home');toast('Backup imported.');}}catch(err){error(err);}});
